const body = $input.first().json.body || {};
const message = (body.message || '').trim();
const resumeToken = body.resume_token || null;
const contactEmail = body.contact_email || null;
const contactName = body.contact_name || null;
if (!message) {
  return [{ json: { valid: false, error: 'message obligatorio' } }];
}
return [{ json: { valid: true, message, resume_token: resumeToken, contact_email: contactEmail, contact_name: contactName } }];

const session = $('Get Or Create Session').first().json;
const input = $('Parse Input').first().json;
const baseline = $input.first().json || {};

const messages = Array.isArray(session.messages) ? session.messages : (typeof session.messages === 'string' ? JSON.parse(session.messages) : []);
const sectionsCovered = typeof session.sections_covered === 'string' ? JSON.parse(session.sections_covered) : (session.sections_covered || {});

messages.push({ role: 'user', content: input.message, ts: new Date().toISOString() });

const sectionLabels = {
  identity: '1. Identidad del estudio (nombre, persona principal, ciudad, ámbito, tamaño, años exp)',
  tone: '2. Tono de comunicación (formal/cercano, técnico/llano, ejemplos)',
  priorities: '3. Prioridades absolutas (5-10 reglas en orden)',
  red_lines: '4. Líneas rojas (cosas que NUNCA hace)',
  visit_checklist: '5. Checklist visita inicial (datos que SIEMPRE pregunta)',
  materials_pref: '6. Preferencias materiales/proveedores',
  trades_pref: '7. Criterios de selección de gremios y mapa trade→contacto',
  jurisdiction: '8. Jurisdicción (CCAA, ayuntamientos habituales, normativa adicional)'
};

const sectionsNeeded = Object.entries(sectionsCovered)
  .filter(([k, v]) => !v)
  .map(([k]) => sectionLabels[k])
  .join('\n');

const sectionsAlreadyCovered = Object.entries(sectionsCovered)
  .filter(([k, v]) => v)
  .map(([k]) => sectionLabels[k])
  .join('\n') || '(ninguna todavía)';

const baselineHint = baseline && baseline.identity
  ? '\n\nBASELINE de referencia (perfil predeterminado de un arquitecto técnico español tipo, lo puedes ofrecer si el usuario va perdido o quiere ahorrarse responder y solo afinar lo distinto):\n```json\n' + JSON.stringify({
      identity: baseline.identity,
      tone: baseline.tone,
      priorities: baseline.priorities,
      red_lines: baseline.red_lines,
      visit_checklist: baseline.visit_checklist
    }, null, 2).substring(0, 1800) + '\n```'
  : '';

const systemPrompt = `Eres el asistente de onboarding de ArquitAI, un software de gestión para estudios de arquitectura técnica. Estás entrevistando al profesional que acaba de comprar el sistema para personalizarlo a su forma de trabajar.

**Tu objetivo**: cubrir 8 áreas de información sobre el estudio del profesional. Tienes que sacarlas conversando, NO con una lista de preguntas tipo formulario. Sé natural, profesional, breve. Reformula con tus palabras lo que el usuario te diga para confirmar que entendiste, y pasa al siguiente tema.

**Áreas que aún FALTAN cubrir**:
${sectionsNeeded || '(todas las 8 áreas ya están cubiertas — propón cerrar la sesión)'}

**Áreas ya cubiertas (no preguntes de nuevo)**:
${sectionsAlreadyCovered}
${baselineHint}

**Reglas estrictas de salida**:
- Tu respuesta DEBE ser un único objeto JSON válido, sin markdown, sin texto adicional.
- Estructura EXACTA: {"message": "...", "sections_now_covered": ["...","..."], "ready_to_close": false}
  - "message": el texto que ve el usuario, conversacional, en español, sin sonar robótico.
  - "sections_now_covered": lista de áreas (identity, tone, priorities, red_lines, visit_checklist, materials_pref, trades_pref, jurisdiction) que con la respuesta actual del usuario quedan cubiertas. Solo añadir si tienes información concreta y suficiente. NUNCA marcar una sección que ya estaba en "ya cubiertas".
  - "ready_to_close": true SOLO si las 8 áreas están cubiertas O si el usuario dice explícitamente que quiere terminar / aceptar el baseline tal cual / cerrar la sesión.

**Reglas de conducta conversacional**:
- Saludar solo en el primer mensaje (cuando el histórico esté vacío o tenga 1 entrada del user).
- No hacer 3 preguntas a la vez. Una pregunta principal, máximo una sub-pregunta.
- Si el usuario va lento o pide ayuda, ofrécele el baseline para esa sección y pídele que solo confirme o ajuste.
- Si el usuario dice algo vago ("normal", "lo típico"), pídele un ejemplo concreto.
- Cuando empieces el cierre (8/8 cubiertas), resume lo que has entendido en 4-5 líneas y pregunta si quiere editar algo antes de guardar.

Recuerda: SOLO devuelve el JSON. No añadas explicaciones fuera del JSON.`;

const conversationText = messages.map(m => (m.role === 'user' ? 'USUARIO: ' : 'ASISTENTE: ') + m.content).join('\n\n');

return [{
  json: {
    agent_name: 'agent_onboarding',
    project_id: null,
    prompt_system: systemPrompt,
    prompt_user: conversationText,
    model: 'gpt-4o',
    temperature: 0.5,
    _session_id: session.id,
    _resume_token: session.resume_token,
    _messages_pre: messages,
    _sections_covered: sectionsCovered,
    _llm_total_cost_usd: Number(session.llm_total_cost_usd || 0),
    _llm_total_tokens: Number(session.llm_total_tokens || 0),
    _llm_message_count: Number(session.llm_message_count || 0)
  }
}];

const llm = $input.first().json;
const preState = $('Build LLM Prompt').first().json;
const raw = (llm.text || '').trim();

let parsed;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : null;
} catch(e) { parsed = null; }

if (!parsed || typeof parsed.message !== 'string') {
  parsed = {
    message: raw || 'Disculpa, ha habido un problema procesando tu respuesta. ¿Puedes reformularla?',
    sections_now_covered: [],
    ready_to_close: false
  };
}

const validSections = ['identity','tone','priorities','red_lines','visit_checklist','materials_pref','trades_pref','jurisdiction'];
const sectionsCovered = { ...preState._sections_covered };
for (const s of (parsed.sections_now_covered || [])) {
  if (validSections.includes(s)) sectionsCovered[s] = true;
}

const messagesPost = [...preState._messages_pre, {
  role: 'assistant',
  content: parsed.message,
  ts: new Date().toISOString(),
  llm_meta: {
    model: llm.model,
    tokens_in: llm.tokens_in,
    tokens_out: llm.tokens_out,
    cost: llm.cost_estimated
  }
}];

return [{
  json: {
    session_id: preState._session_id,
    resume_token: preState._resume_token,
    response_message: parsed.message,
    sections_covered: sectionsCovered,
    ready_to_close: !!parsed.ready_to_close,
    messages_json: JSON.stringify(messagesPost),
    sections_covered_json: JSON.stringify(sectionsCovered),
    cost_total: preState._llm_total_cost_usd + Number(llm.cost_estimated || 0),
    tokens_total: preState._llm_total_tokens + Number(llm.tokens_in || 0) + Number(llm.tokens_out || 0),
    message_count: preState._llm_message_count + 1
  }
}];
